namespace neos::python_runtime::detail::http_cookiejar_docs
{
    struct entry { char const* name; char const* doc; };
    inline entry const sDocs[] =
    {
        { "", "HTTP cookie handling for web clients.\n\nThis module has (now fairly distant) origins in Gisle Aas' Perl module\nHTTP::Cookies, from the libwww-perl library.\n\nDocstrings, comments and debug strings in this code refer to the\nattributes of the HTTP cookie system as cookie-attributes, to distinguish\nthem clearly from Python attributes.\n\nClass diagram (note that BSDDBCookieJar and the MSIE* classes are not\ndistributed with the Python standard library, but are available from\nhttp://wwwsearch.sf.net/):\n\n                        CookieJar____\n                        /     \\      \\\n            FileCookieJar      \\      \\\n             /    |   \\         \\      \\\n MozillaCookieJar | LWPCookieJar \\      \\\n                  |               |      \\\n                  |   ---MSIEBase |       \\\n                  |  /      |     |        \\\n                  | /   MSIEDBCookieJar BSDDBCookieJar\n                  |/\n               MSIECookieJar\n\n" },
        { "Cookie", "HTTP Cookie.\n\nThis class represents both Netscape and RFC 2965 cookies.\n\nThis is deliberately a very simple class.  It just holds attributes.  It's\npossible to construct Cookie instances that don't comply with the cookie\nstandards.  CookieJar.make_cookies is the factory function for Cookie\nobjects -- it deals with cookie parsing, supplying defaults, and\nnormalising to the representation used in this class.  CookiePolicy is\nresponsible for checking them to see whether they should be accepted from\nand returned to the server.\n\nNote that the port may be present in the headers, but unspecified (\"Port\"\nrather than\"Port=80\", for example); if this is the case, port is None.\n\n" },
        { "CookieJar", "Collection of HTTP cookies.\n\nYou may not need to know about this class: try\nurllib.request.build_opener(HTTPCookieProcessor).open(url).\n" },
        { "CookieJar._cookies_for_request", "Return a list of cookies to be returned to server." },
        { "CookieJar._cookie_attrs", "Return a list of cookie-attributes to be returned to server.\n\nlike ['foo=\"bar\"; $Path=\"/\"', ...]\n\nThe $Version attribute is also added when appropriate (currently only\nonce per request).\n\n" },
        { "CookieJar.add_cookie_header", "Add correct Cookie: header to request (urllib.request.Request object).\n\nThe Cookie2 header is also added unless policy.hide_cookie2 is true.\n\n" },
        { "CookieJar._normalized_cookie_tuples", "Return list of tuples containing normalised cookie information.\n\nattrs_set is the list of lists of key,value pairs extracted from\nthe Set-Cookie or Set-Cookie2 headers.\n\nTuples are name, value, standard, rest, where name and value are the\ncookie name and value, standard is a dictionary containing the standard\ncookie-attributes (discard, secure, version, expires or max-age,\ndomain, path and port) and rest is a dictionary containing the rest of\nthe cookie-attributes.\n\n" },
        { "CookieJar.make_cookies", "Return sequence of Cookie objects extracted from response object." },
        { "CookieJar.set_cookie_if_ok", "Set a cookie if policy says it's OK to do so." },
        { "CookieJar.set_cookie", "Set a cookie, without checking whether or not it should be set." },
        { "CookieJar.extract_cookies", "Extract cookies from response, where allowable given the request." },
        { "CookieJar.clear", "Clear some cookies.\n\nInvoking this method without arguments will clear all cookies.  If\ngiven a single argument, only cookies belonging to that domain will be\nremoved.  If given two arguments, cookies belonging to the specified\npath within that domain are removed.  If given three arguments, then\nthe cookie with the specified name, path and domain is removed.\n\nRaises KeyError if no matching cookie exists.\n\n" },
        { "CookieJar.clear_session_cookies", "Discard all session cookies.\n\nNote that the .save() method won't save session cookies anyway, unless\nyou ask otherwise by passing a true ignore_discard argument.\n\n" },
        { "CookieJar.clear_expired_cookies", "Discard all expired cookies.\n\nYou probably don't need to call this method: expired cookies are never\nsent back to the server (provided you're using DefaultCookiePolicy),\nthis method is called by CookieJar itself every so often, and the\n.save() method won't save expired cookies anyway (unless you ask\notherwise by passing a true ignore_expires argument).\n\n" },
        { "CookieJar.__len__", "Return number of contained cookies." },
        { "CookiePolicy", "Defines which cookies get accepted from and returned to server.\n\nMay also modify cookies, though this is probably a bad idea.\n\nThe subclass DefaultCookiePolicy defines the standard rules for Netscape\nand RFC 2965 cookies -- override that if you want a customized policy.\n\n" },
        { "CookiePolicy.set_ok", "Return true if (and only if) cookie should be accepted from server.\n\nCurrently, pre-expired cookies never get this far -- the CookieJar\nclass deletes such cookies itself.\n\n" },
        { "CookiePolicy.return_ok", "Return true if (and only if) cookie should be returned to server." },
        { "CookiePolicy.domain_return_ok", "Return false if cookies should not be returned, given cookie domain.\n        " },
        { "CookiePolicy.path_return_ok", "Return false if cookies should not be returned, given cookie path.\n        " },
        { "DefaultCookiePolicy", "Implements the standard rules for accepting and returning cookies." },
        { "DefaultCookiePolicy.__init__", "Constructor arguments should be passed as keyword arguments only." },
        { "DefaultCookiePolicy.blocked_domains", "Return the sequence of blocked domains (as a tuple)." },
        { "DefaultCookiePolicy.set_blocked_domains", "Set the sequence of blocked domains." },
        { "DefaultCookiePolicy.allowed_domains", "Return None, or the sequence of allowed domains (as a tuple)." },
        { "DefaultCookiePolicy.set_allowed_domains", "Set the sequence of allowed domains, or None." },
        { "DefaultCookiePolicy.set_ok", "\nIf you override .set_ok(), be sure to call this method.  If it returns\nfalse, so should your subclass (assuming your subclass wants to be more\nstrict about which cookies to accept).\n\n" },
        { "DefaultCookiePolicy.return_ok", "\nIf you override .return_ok(), be sure to call this method.  If it\nreturns false, so should your subclass (assuming your subclass wants to\nbe more strict about which cookies to return).\n\n" },
        { "FileCookieJar", "CookieJar that can be loaded from and saved to a file." },
        { "FileCookieJar.__init__", "\nCookies are NOT loaded from the named file until either the .load() or\n.revert() method is called.\n\n" },
        { "FileCookieJar.save", "Save cookies to a file." },
        { "FileCookieJar.load", "Load cookies from a file." },
        { "FileCookieJar.revert", "Clear all cookies and reload cookies from a saved file.\n\nRaises LoadError (or OSError) if reversion is not successful; the\nobject's state will not be altered if this happens.\n\n" },
        { "LWPCookieJar", "\nThe LWPCookieJar saves a sequence of \"Set-Cookie3\" lines.\n\"Set-Cookie3\" is the format used by the libwww-perl library, not known\nto be compatible with any browser, but which is easy to read and\ndoesn't lose information about RFC 2965 cookies.\n\nAdditional methods\n\nas_lwp_str(ignore_discard=True, ignore_expired=True)\n\n" },
        { "LWPCookieJar.as_lwp_str", "Return cookies as a string of \"\\n\"-separated \"Set-Cookie3\" headers.\n\nignore_discard and ignore_expires: see docstring for FileCookieJar.save\n\n" },
        { "MozillaCookieJar", "\n\nWARNING: you may want to backup your browser's cookies file if you use\nthis class to save cookies.  I *think* it works, but there have been\nbugs in the past!\n\nThis class differs from CookieJar only in the format it uses to save and\nload cookies to and from a file.  This class uses the Mozilla/Netscape\n`cookies.txt' format.  curl and lynx use this file format, too.\n\nDon't expect cookies saved while the browser is running to be noticed by\nthe browser (in fact, Mozilla on unix will overwrite your saved cookies if\nyou change them on disk while it's running; on Windows, you probably can't\nsave at all while the browser is running).\n\nNote that the Mozilla/Netscape format will downgrade RFC2965 cookies to\nNetscape cookies on saving.\n\nIn particular, the cookie version and port number information is lost,\ntogether with information about whether or not Path, Port and Discard were\nspecified by the Set-Cookie2 (or Set-Cookie) header, and whether or not the\ndomain as set in the HTTP header started with a dot (yes, I'm aware some\ndomains in Netscape files start with a dot and some don't -- trust me, you\nreally don't want to know any more about this).\n\nNote that though Mozilla and Netscape use the same format, they use\nslightly different headers.  The class saves cookies using the Netscape\nheader by default (Mozilla can cope with that).\n\n" },
        { "deepvalues", "Iterates over nested mapping, depth-first" },
        { "domain_match", "Return True if domain A domain-matches domain B, according to RFC 2965.\n\nA and B may be host domain names or IP addresses.\n\nRFC 2965, section 1:\n\nHost names can be specified either as an IP address or a HDN string.\nSometimes we compare one host name with another.  (Such comparisons SHALL\nbe case-insensitive.)  Host A's name domain-matches host B's if\n\n     *  their host name strings string-compare equal; or\n\n     * A is a HDN string and has the form NB, where N is a non-empty\n        name string, B has the form .B', and B' is a HDN string.  (So,\n        x.y.com domain-matches .Y.com but not Y.com.)\n\nNote that domain-match is not a commutative operation: a.b.c.com\ndomain-matches .c.com, but not the reverse.\n\n" },
        { "eff_request_host", "Return a tuple (request-host, effective request-host name).\n\nAs defined by RFC 2965, except both are lowercased.\n\n" },
        { "escape_path", "Escape any invalid characters in HTTP URL, and uppercase all escapes." },
        { "http2time", "Returns time in seconds since epoch of time represented by a string.\n\nReturn value is an integer.\n\nNone is returned if the format of str is unrecognized, the time is outside\nthe representable range, or the timezone string is not recognized.  If the\nstring contains no timezone, UTC is assumed.\n\nThe timezone in the string may be numerical (like \"-0800\" or \"+0100\") or a\nstring timezone (like \"UTC\", \"GMT\", \"BST\" or \"EST\").  Currently, only the\ntimezone strings equivalent to UTC (zero offset) are known to the function.\n\nThe function loosely parses the following formats:\n\nWed, 09 Feb 1994 22:23:32 GMT       -- HTTP format\nTuesday, 08-Feb-94 14:15:29 GMT     -- old rfc850 HTTP format\nTuesday, 08-Feb-1994 14:15:29 GMT   -- broken rfc850 HTTP format\n09 Feb 1994 22:23:32 GMT            -- HTTP format (no weekday)\n08-Feb-94 14:15:29 GMT              -- rfc850 format (no weekday)\n08-Feb-1994 14:15:29 GMT            -- broken rfc850 format (no weekday)\n\nThe parser ignores leading and trailing whitespace.  The time may be\nabsent.\n\nIf the year is given with only 2 digits, the function will select the\ncentury that makes the year closest to the current date.\n\n" },
        { "is_HDN", "Return True if text is a host domain name." },
        { "is_third_party", "\n\nRFC 2965, section 3.3.6:\n\n    An unverifiable transaction is to a third-party host if its request-\n    host U does not domain-match the reach R of the request-host O in the\n    origin transaction.\n\n" },
        { "iso2time", "\nAs for http2time, but parses the ISO 8601 formats:\n\n1994-02-03 14:15:29 -0100    -- ISO 8601 format\n1994-02-03 14:15:29          -- zone is optional\n1994-02-03                   -- only date\n1994-02-03T14:15:29          -- Use T as separator\n19940203T141529Z             -- ISO 8601 compact format\n19940203                     -- only date\n\n" },
        { "join_header_words", "Do the inverse (almost) of the conversion done by split_header_words.\n\nTakes a list of lists of (key, value) pairs and produces a single header\nvalue.  Attribute values are quoted if needed.\n\n>>> join_header_words([[(\"text/plain\", None), (\"charset\", \"iso-8859/1\")]])\n'text/plain; charset=\"iso-8859/1\"'\n>>> join_header_words([[(\"text/plain\", None)], [(\"charset\", \"iso-8859/1\")]])\n'text/plain, charset=\"iso-8859/1\"'\n\n" },
        { "liberal_is_HDN", "Return True if text is a sort-of-like a host domain name.\n\nFor accepting/blocking domains.\n\n" },
        { "lwp_cookie_str", "Return string representation of Cookie in the LWP cookie file format.\n\nActually, the format is extended a bit -- see module docstring.\n\n" },
        { "parse_ns_headers", "Ad-hoc parser for Netscape protocol cookie-attributes.\n\nThe old Netscape cookie format for Set-Cookie can for instance contain\nan unquoted \",\" in the expires field, so we have to use this ad-hoc\nparser instead of split_header_words.\n\nXXX This may not make the best possible effort to parse all the crap\nthat Netscape Cookie headers contain.  Ronald Tschalar's HTTPClient\nparser is probably better, so could do worse than following that if\nthis ever gives any trouble.\n\nCurrently, this is also used for parsing RFC 2109 cookies.\n\n" },
        { "reach", "Return reach of host h, as defined by RFC 2965, section 1.\n\nThe reach R of a host name H is defined as follows:\n\n   *  If\n\n      -  H is the host domain name of a host; and,\n\n      -  H has the form A.B; and\n\n      -  A has no embedded (that is, interior) dots; and\n\n      -  B has at least one embedded dot, or B is the string \"local\".\n         then the reach of H is .B.\n\n   *  Otherwise, the reach of H is H.\n\n>>> reach(\"www.acme.com\")\n'.acme.com'\n>>> reach(\"acme.com\")\n'acme.com'\n>>> reach(\"acme.local\")\n'.local'\n\n" },
        { "request_host", "Return request-host, as defined by RFC 2965.\n\nVariation from RFC: returned value is lowercased, for convenient\ncomparison.\n\n" },
        { "request_path", "Path component of request-URI, as defined by RFC 2965." },
        { "split_header_words", "Parse header values into a list of lists containing key,value pairs.\n\nThe function knows how to deal with \",\", \";\" and \"=\" as well as quoted\nvalues after \"=\".  A list of space separated tokens are parsed as if they\nwere separated by \";\".\n\nIf the header_values passed as argument contains multiple values, then they\nare treated as if they were a single value separated by comma \",\".\n\nThis means that this function is useful for parsing header fields that\nfollow this syntax (BNF as from the HTTP/1.1 specification, but we relax\nthe requirement for tokens).\n\n  headers           = #header\n  header            = (token | parameter) *( [\";\"] (token | parameter))\n\n  token             = 1*<any CHAR except CTLs or separators>\n  separators        = \"(\" | \")\" | \"<\" | \">\" | \"@\"\n                    | \",\" | \";\" | \":\" | \"\\\" | <\">\n                    | \"/\" | \"[\" | \"]\" | \"?\" | \"=\"\n                    | \"{\" | \"}\" | SP | HT\n\n  quoted-string     = ( <\"> *(qdtext | quoted-pair ) <\"> )\n  qdtext            = <any TEXT except <\">>\n  quoted-pair       = \"\\\" CHAR\n\n  parameter         = attribute \"=\" value\n  attribute         = token\n  value             = token | quoted-string\n\nEach header is represented by a list of key/value pairs.  The value for a\nsimple token (not part of a parameter) is None.  Syntactically incorrect\nheaders will not necessarily be parsed as you would want.\n\nThis is easier to describe with some examples:\n\n>>> split_header_words(['foo=\"bar\"; port=\"80,81\"; discard, bar=baz'])\n[[('foo', 'bar'), ('port', '80,81'), ('discard', None)], [('bar', 'baz')]]\n>>> split_header_words(['text/html; charset=\"iso-8859-1\"'])\n[[('text/html', None), ('charset', 'iso-8859-1')]]\n>>> split_header_words([r'Basic realm=\"\\\"foo\\bar\\\"\"'])\n[[('Basic', None), ('realm', '\"foobar\"')]]\n\n" },
        { "time2isoz", "Return a string representing time in seconds since epoch, t.\n\nIf the function is called without an argument, it will use the current\ntime.\n\nThe format of the returned string is like \"YYYY-MM-DD hh:mm:ssZ\",\nrepresenting Universal Time (UTC, aka GMT).  An example of this format is:\n\n1994-11-24 08:49:37Z\n\n" },
        { "time2netscape", "Return a string representing time in seconds since epoch, t.\n\nIf the function is called without an argument, it will use the current\ntime.\n\nThe format of the returned string is like this:\n\nWed, DD-Mon-YYYY HH:MM:SS GMT\n\n" },
        { "unmatched", "Return unmatched part of re.Match object." },
        { "user_domain_match", "For blocking/accepting domains.\n\nA and B may be host domain names or IP addresses.\n\n" },
    };
    inline char const* doc(char const* aName)
    {
        for (auto const& e : sDocs)
            if (std::strcmp(e.name, aName) == 0)
                return e.doc;
        return nullptr;
    }
}
